{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-rows.json
    The features as rows: text beside a picture (the rows layout of FeatureGrid). Icons are Lucide names.
    Props (p): features, mediaSide. *}
{var $v_features = ($p['features'] ?? null)}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{capture $c_6}
  {foreach ui_l($v_features) as $v_feature}
    {capture $c_5}
      {capture $c_3}
        {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_feature, ['icon'])), 'Size' => 24]])|noescape}
        {capture $c_1}
          {=ui_text(ui_get($v_feature, ['title']))}
        {/capture}
        {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'xl', 'Weight' => 'bold'], 'children' => $c_1])|noescape}
        {capture $c_2}
          {=ui_text(ui_get($v_feature, ['text']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Class' => 'text-muted-foreground'], 'children' => $c_2])|noescape}
      {/capture}
      {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '2', 'Class' => 'min-w-0'], 'children' => $c_3])|noescape}
      {capture $c_4}
        {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_feature, ['title']), 'ratio' => '4/3']])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => ui_s(ui_cnv(['w-full min-w-0', (ui_t(ui_eq($v_mediaSide, 'start')) ? 'md:order-first' : (ui_t(ui_eq($v_mediaSide, 'alternate')) ? 'md:group-even:order-first' : ''))]))], 'children' => $c_4])|noescape}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-2', 'Class' => 'group items-center gap-8', 'Attrs' => ui_attrs(['data-testid', 'feature-card'])], 'children' => $c_5])|noescape}
  {/foreach}
{/capture}
{=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '8', 'Align' => 'stretch', 'Attrs' => ui_attrs(['data-testid', 'feature-rows'])], 'children' => $c_6])|noescape}
